{
  "technical_and_design_decisions": [
    "Implement in Go by extending the Hyperledger Fabric config (fabric-config) channel configuration library, following its existing conventions for manipulating cb.ConfigGroup-based config transactions.",
    "U1 retrieval functions (application, orderer, consortium orgs) parse the config transaction's ConfigGroup tree and return populated Organization structs, so callers can modify fields and pass them to existing update-org functions.",
    "U2/U3/U4 policy add/remove functions mutate the supplied ConfigGroup in place (add or remove named policies on the org or group level, including Application, Orderer, Consortiums/Consortium groups) and return only an error, enabling chaining of further updates on the same config transaction.",
    "U5/U6 add-org functions construct a new org ConfigGroup (MSP, policies, anchor peers for application orgs, endpoints for orderer orgs) and attach it to the channel config, returning the mutated config transaction.",
    "U7 MSP retrieval unmarshals the org's MSP configuration into a FabricMSPConfig wrapper for direct reuse of CA certs and related fields.",
    "U8 RevokeCertificate builds an in-memory MSP from the org's FabricMSPConfig, uses standard x509/MSP validation to verify the certificate was issued by that MSP (error otherwise), and appends the certificate identifier to the FabricMSPConfig revocation_list attribute.",
    "All exported functions get godoc comments; every story's acceptance includes updating Go example tests (ExampleXxx) to demonstrate usage; unit tests use table-driven tests with existing test fixtures."
  ],
  "assumptions": [
    "A single experienced Go developer already familiar with Hyperledger Fabric config transaction structures (protobufs: cb.Config, cb.ConfigGroup, msp.FabricMSPConfig) performs all work.",
    "The existing fabric-config codebase with its established patterns, helpers, and test fixtures (sample orgs, certs, base config transactions) is the starting point; no greenfield setup is needed.",
    "Example-test updates required by each story's acceptance criteria are included in that story's activity estimate.",
    "Standard Go toolchain and existing CI (go test, vet, lint) are used; no changes to build/CI infrastructure are required.",
    "There are no non-functional requirements beyond correctness (no performance, UI, or deployment work); scope is API/library code, unit tests, example tests, and inline documentation.",
    "Reasonable schedule risk (minor rework from review feedback) is covered by a dedicated code-review/rework activity.",
    "Effort is estimated as net development effort in workdays, independent of elapsed calendar time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and API design",
      "activity_description": "Analyze U1-U8, design exported function signatures, return types, error-handling conventions, and internal helper reuse across retrieval, policy-update, add-org, MSP-retrieval, and revocation features.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Retrieve organization configuration",
      "activity_description": "Implement functions to retrieve application, orderer, and consortium organization configuration from a config transaction as a config.Organization, plus unit tests and updated example tests demonstrating retrieve-modify-update usage.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Add/remove policies on application org and application group",
      "activity_description": "Implement add/remove policy functions for an application org and for the application group within a config transaction, with unit tests and example test updates.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A4",
      "activity_name": "U3: Add/remove policies on orderer org and orderer group",
      "activity_description": "Implement add/remove policy functions for an orderer org and for the orderer group within a config transaction, with unit tests and example test updates.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A5",
      "activity_name": "U4: Add/remove policies on consortium org, consortiums group, and consortium group",
      "activity_description": "Implement add/remove policy functions covering a consortium org, the consortiums group, and an individual consortium group, with unit tests and example test updates.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: Add orderer organization to channel configuration",
      "activity_description": "Implement a function that adds a complete orderer org definition (MSP, policies, endpoints) to a channel config transaction so it can be further mutated, with unit tests and example test updates.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "U6: Add application organization to channel configuration",
      "activity_description": "Implement a function that adds a complete application org definition (MSP, policies, anchor peers) to a channel config transaction, reusing helpers from U5, with unit tests and example test updates.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A8",
      "activity_name": "U7: Retrieve MSP configuration for an organization",
      "activity_description": "Implement a function returning the FabricMSPConfig for a specified org from a config transaction, with unit tests and example test updates.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "U8: Revoke certificate issued by an org's MSP",
      "activity_description": "Implement certificate revocation: verify the provided certificate was issued by the org's MSP (error if not) and update the revocation_list attribute of FabricMSPConfig in the config transaction, with unit tests and example test updates.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration and regression testing",
      "activity_description": "Run and extend end-to-end scenarios chaining the new functions (retrieve -> modify -> update -> add org -> revoke), execute full test suite, and fix defects.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation",
      "activity_description": "Write godoc comments for all new exported functions and update package-level documentation/README snippets describing the new capabilities.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A12",
      "activity_name": "Code review and rework",
      "activity_description": "Self-review, address reviewer feedback, refactor for consistency with existing codebase patterns, and finalize the increment.",
      "most_likely_effort": 1.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 27.5
  }
}

